CREATE OR REPLACE FUNCTION research.run_library_display_kind(profile_id text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,research AS $$
 SELECT CASE profile_id
 WHEN 'p04.fixed-qualification.v1' THEN 'P04'
 WHEN 'p10.vn-stock-daily-observed-fixed.v1' THEN 'VN'
 WHEN 'p10.delta-signal-notional-wfo.v1' THEN 'WFO'
 WHEN 'p10.delta-signal-notional-wfo.v2' THEN 'WFO'
 WHEN 'p10.delta-signal-notional-causal-inner.v1' THEN 'WFO'
 WHEN 'p10.delta-signal-notional-per-fold-decay.v1' THEN 'WFO'
 WHEN 'p10.delta-signal-notional-three-window-optimized.v1' THEN 'OPT'
 WHEN 'p10.delta-wfo-temporal-1m.v1' THEN 'WFO'
 WHEN 'p10.delta-causal-inner-1m.v1' THEN 'WFO'
 WHEN 'p10.delta-per-fold-decay-1m.v1' THEN 'WFO'
 WHEN 'p10.delta-three-window-optimized-1m.v1' THEN 'OPT'
 WHEN 'p10.delta-wfo-temporal-5m.v1' THEN 'WFO'
 WHEN 'p10.delta-causal-inner-5m.v1' THEN 'WFO'
 WHEN 'p10.delta-per-fold-decay-5m.v1' THEN 'WFO'
 WHEN 'p10.delta-three-window-optimized-5m.v1' THEN 'OPT'
 WHEN 'p10.delta-wfo-temporal-15m.v1' THEN 'WFO'
 WHEN 'p10.delta-causal-inner-15m.v1' THEN 'WFO'
 WHEN 'p10.delta-per-fold-decay-15m.v1' THEN 'WFO'
 WHEN 'p10.delta-three-window-optimized-15m.v1' THEN 'OPT'
 WHEN 'p10.delta-wfo-temporal-30m.v1' THEN 'WFO'
 WHEN 'p10.delta-causal-inner-30m.v1' THEN 'WFO'
 WHEN 'p10.delta-per-fold-decay-30m.v1' THEN 'WFO'
 WHEN 'p10.delta-three-window-optimized-30m.v1' THEN 'OPT'
 WHEN 'p10.delta-wfo-temporal-1h.v1' THEN 'WFO'
 WHEN 'p10.delta-causal-inner-1h.v1' THEN 'WFO'
 WHEN 'p10.delta-per-fold-decay-1h.v1' THEN 'WFO'
 WHEN 'p10.delta-three-window-optimized-1h.v1' THEN 'OPT'
 WHEN 'p10.delta-wfo-temporal-4h.v1' THEN 'WFO'
 WHEN 'p10.delta-causal-inner-4h.v1' THEN 'WFO'
